tests.code:
for name in ["IDTA", "Addendum", "BCR"]:
    got = transfer_route(False, name, True)
    assert got == "safeguards", (name, got)

try:
    transfer_route(False, "IDTA", None)
except ValueError:
    pass
else:
    raise AssertionError("no ValueError for a missing TRA")

try:
    transfer_route(False, "a handshake", True)
except ValueError:
    pass
else:
    raise AssertionError("no ValueError for an unknown safeguard")

